class Solution:
    def maxProduct(self, nums: List[int]) -> int:
        max_prod = min_prod = result = nums[0]
        for n in nums[1:]:
            curr_max = max(n, max_prod * n, min_prod * n)
            curr_min = min(n, max_prod * n, min_prod * n)
            max_prod, min_prod = curr_max, curr_min
            result = max(result, max_prod)
        return result

reference_solution.javascript:
function maxProduct(nums) {
    let maxProd = nums[0], minProd = nums[0], result = nums[0];
    for (let i = 1; i < nums.length; i++) {
        const n = nums[i];
        const currMax = Math.max(n, maxProd * n, minProd * n);
        const currMin = Math.min(n, maxProd * n, minProd * n);
        maxProd = currMax;
        minProd = currMin;
        result = Math.max(result, maxProd);
    }
    return result;
}
